 static int Number(string[] args,string name,int fallback){string raw=Arg(args,name,null);if(raw==null)return fallback;int value;if(!Int32.TryParse(raw,NumberStyles.Integer,CultureInfo.InvariantCulture,out value))throw new ArgumentException("Invalid integer for "+name+".");return value;}
