 static void State(string root,int pid,string phase,object detail){EngineJson.Write(Path.Combine(root,"auto-campaign-state.json"),new Dictionary<string,object>{{"WorkerPid",pid},{"Updated",DateTime.Now.ToString("o",CultureInfo.InvariantCulture)},{"Phase",phase},{"Detail",detail}});}
