 static bool StopRequested(string root){return File.Exists(Path.Combine(root,"auto-campaign-stop.request"));}
 static ulong ReadPtr(int pid,ulong address){return BitConverter.ToUInt64(Read(pid,address,8),0);}
 static uint ReadU32(int pid,ulong address){return BitConverter.ToUInt32(Read(pid,address,4),0);}
