  string stopPath=Path.Combine(root,"auto-campaign-stop.request");var mutex=new Mutex(false,"Local\\SC2CampaignAuto97563");bool owned=false;SC2HubCamera hubCamera=null;SC2MissionZoom missionZoom=null;
