   if(game==null)throw new TimeoutException("StarCraft II did not start within ten minutes.");int pid=game.Id;string expectedExe=game.MainModule.FileName;SC2AutoStart.ValidateExecutable(expectedExe,game.MainModule.FileVersionInfo.FileVersion);Log(root,"Detected StarCraft II PID "+pid+".");State(root,workerPid,"Waiting for offline campaign",Detail("GamePid",pid));
