   module=(ulong)game.MainModule.BaseAddress.ToInt64();hubCamera=new SC2HubCamera(pid,module,Path.Combine(root,"hub-camera-session.txt"));missionZoom=new SC2MissionZoom(pid,module,Path.Combine(root,"mission-zoom-session.txt"));var refresh=new SC2DisplayRefreshSchedule();var timer=Stopwatch.StartNew();string refreshPhase="",lastHubStatus="",context="",hudReady="",lastError="",lastZoomError="",pendingHud="";DateTime attemptAfter=DateTime.Now,pendingSince=DateTime.Now;int lastWidth=0,lastHeight=0;bool blocked=false;ulong contextOwner=0;
   while(!game.HasExited){
