     if(w!=lastWidth||h!=lastHeight){Log(root,"Display "+w+"x"+h+".");string phase=w==width&&h==height?"Waiting for campaign mission":"Preparing campaign display";State(root,workerPid,phase,Detail("GamePid",pid,"Width",w,"Height",h,"StartupOverrides",ReadU32(pid,attached.State+36)));lastWidth=w;lastHeight=h;}
     ulong uiNow=ReadPtr(pid,module+SC2Addresses.Rva(0x4032368));bool uiReady=uiNow!=0&&ReadPtr(pid,uiNow)==module+SC2Addresses.Rva(0x2D522A8);bool atTarget=w==width&&h==height;string displayContext=hub.Allowed?"Hub:"+hub.Key:eligibility.MapPath;string refreshKey=displayContext+":"+uiNow.ToString("X")+":"+device.ToString("X");bool focused=uiReady&&SC2CampaignDisplayRefresh.IsForeground(pid);string decision=refresh.Observe(refreshKey,focused,atTarget,timer.Elapsed.TotalMilliseconds);
     if(!atTarget){string phase="Preparing campaign display";if(decision=="Focus")phase="Return to campaign";else if(decision=="Failed")phase="Display setup paused";else if(decision=="Request"){string result=SC2CampaignDisplayRefresh.Request(pid,module,device,attached.VTable,attached.State);if(result=="Requested"){refresh.Requested(timer.Elapsed.TotalMilliseconds);Log(root,"Queued the normal graphics-settings update for this campaign.");phase="Applying campaign resolution";}else if(result=="Waiting for fullscreen mode")phase="Waiting for fullscreen";}else if(decision=="Pending")phase="Applying campaign resolution";if(phase!=refreshPhase){State(root,workerPid,phase,Detail("GamePid",pid,"Width",w,"Height",h));refreshPhase=phase;}Sleep(100);continue;}
     refreshPhase="";if(hub.Allowed){bool cameraReady=hubCamera.Tick(hub,hubScale,(double)width/height);string status=hub.Key+":"+hubScale+":"+cameraReady;if(status!=lastHubStatus){State(root,workerPid,cameraReady?"Ready":"Preparing campaign display",cameraReady?(object)Detail("GamePid",pid,"Width",w,"Height",h,"Hub",true):Detail("GamePid",pid,"Width",w,"Height",h));lastHubStatus=status;}Sleep(25);continue;}
     uiNow=ReadPtr(pid,module+SC2Addresses.Rva(0x4032368));if(uiNow==0||ReadPtr(pid,uiNow)!=module+SC2Addresses.Rva(0x2D522A8)){context="";hudReady="";Sleep(100);continue;}ulong console=ReadPtr(pid,uiNow+0xc60),ownerNow=ReadPtr(pid,uiNow+0xc68),world=ReadPtr(pid,uiNow+0xc18);if(console==0||ownerNow==0||world==0){Sleep(100);continue;}string key=uiNow.ToString("X")+":"+ownerNow.ToString("X")+":"+console.ToString("X")+":"+world.ToString("X")+":"+eligibility.MapPath;
     if(key!=context){scaleResetNeeded=true;reportedScale=-1;context=key;contextOwner=ownerNow;hudReady="";pendingHud="";lastError="";attemptAfter=DateTime.Now.AddMilliseconds(300);}if(scaleResetNeeded){var scaled=EngineControl.Scale(root,"Disable",width,height,hudScale);if(!EngineJson.Bool(scaled,"Ready")){State(root,workerPid,"Applying HUD size",null);Sleep(100);continue;}scaleResetNeeded=false;}
     if(pendingHud==key){var rec=EngineJson.Read(Path.Combine(root,"hud-runtime-session.json"));ulong state=Convert.ToUInt64(Convert.ToString(rec["State"]),16);if(ReadU32(pid,state)==0&&ReadU32(pid,state+4)==0&&ReadU32(pid,state+12)>0){if(Math.Abs(ReadF32(pid,console+0x84)-hudInset)<.01&&Math.Abs(ReadF32(pid,ownerNow+0x84)-hudInset)<.01&&Math.Abs(ReadF32(pid,world+0x94))<.01&&ReadF32(pid,uiNow+0xbfc)==0&&EngineJson.Str(rec,"MenuConsoleAnchor")!=""&&Math.Abs(ReadF32(pid,ReadPtr(pid,uiNow+0xc80)+0xa4)+hudInset)<.01&&Math.Abs(ReadF32(pid,ReadPtr(pid,uiNow+0xc88)+0xa4)+hudInset)<.01){hudReady=key;pendingHud="";Log(root,"Campaign HUD and menu buttons centered; bottom corners filled.");State(root,workerPid,"Applying HUD size",Detail("GamePid",pid,"Width",w,"Height",h));}else{pendingHud="";attemptAfter=DateTime.Now.AddSeconds(1);}}else if((DateTime.Now-pendingSince).TotalSeconds>20){Log(root,"HUD job is waiting for a normal layout callback.");pendingSince=DateTime.Now;}}
     if(hudReady!=key&&pendingHud==""&&DateTime.Now>=attemptAfter){SC2CampaignGate.Require(pid,module);attemptAfter=DateTime.Now.AddSeconds(2);if(ReadPtr(pid,console)!=module+SC2Addresses.Rva(0x2D62E98)||ReadPtr(pid,world)!=module+SC2Addresses.Rva(0x2D6C370))throw new InvalidOperationException("Waiting for the supported campaign console.");EngineControl.Hud(root,"Enable",width,height);pendingHud=key;pendingSince=DateTime.Now;Log(root,"Mission UI ready; queued native HUD and viewport update.");State(root,workerPid,"Applying campaign HUD",Detail("GamePid",pid,"Width",w,"Height",h));}
     if(hudReady==key&&DateTime.Now>=scaleNext){scaleNext=DateTime.Now.AddMilliseconds(500);var scaled=EngineControl.Scale(root,"Enable",width,height,hudScale);if(EngineJson.Bool(scaled,"Ready")){if(reportedScale!=hudScale){Log(root,"Bottom HUD size applied: "+hudScale+"%.");reportedScale=hudScale;}State(root,workerPid,"Ready",Detail("GamePid",pid,"Width",w,"Height",h,"Hud","Centered","HudScale",hudScale,"Corners","Filled","Context",key));}else State(root,workerPid,"Applying HUD size",Detail("GamePid",pid,"HudScale",hudScale));}
