  }catch(Exception ex){if(StopRequested(root)){Log(root,"Automatic helper stopped.");State(root,workerPid,"Stopped",null);return 0;}Log(root,"ERROR: "+ex.Message);State(root,workerPid,"Error",ex.Message);return 1;}
  finally{if(missionZoom!=null)try{missionZoom.Stop();}catch(Exception ex){Log(root,"Zoom restore: "+ex.Message);}if(hubCamera!=null)try{hubCamera.Stop();}catch{}if(owned)mutex.ReleaseMutex();mutex.Dispose();}
 }
